// Run once with: node bundle-drawings.js
// Bundles all drawing JSONs into drawings-bundle.js so they work without a server

const fs = require('fs');
const path = require('path');

const folders = {
  desktop: path.join(__dirname, 'Startup_Drawings', 'Desktop_Drawings'),
  mobile:  path.join(__dirname, 'Startup_Drawings', 'Mobile_Drawings'),
};

const bundle = { desktop: [], mobile: [] };

for (const [key, folder] of Object.entries(folders)) {
  const files = fs.readdirSync(folder).filter(f => f.endsWith('.json')).sort();
  for (const file of files) {
    const data = JSON.parse(fs.readFileSync(path.join(folder, file), 'utf8'));
    bundle[key].push(data);
  }
  console.log(`${key}: ${files.length} drawings loaded`);
}

const output = `// Auto-generated by bundle-drawings.js — do not edit manually\nconst DRAWINGS_BUNDLE = ${JSON.stringify(bundle)};\n`;
fs.writeFileSync(path.join(__dirname, 'drawings-bundle.js'), output);
console.log('✓ drawings-bundle.js created');
